rows.old_complete_signature:
private theorem finrank_adjoin_pow [FiniteDimensional K F] {N e : ℕ}
    (hN : 0 < N) (he : 0 < e) (heN : e ∣ N) {a : K} {θ : F}
    (hθ : θ ^ N = algebraMap K F a) (hgen : K⟮θ⟯ = ⊤)
    (hdegree : finrank K F = N) : finrank K K⟮θ ^ (N / e)⟯ = e

